+++ b/src/filter_core/filter_pck.c
@@ -99,7 +99,6 @@ static GF_FilterPacket *gf_filter_pck_new_alloc_internal(GF_FilterPid *pid, u32
 {
 	GF_FilterPacket *pck=NULL;
 	GF_FilterPacket *closest=NULL;
-	GF_PckQueueEnum pck_enum_state;
 	u32 count, max_reservoir_size;

 	if (PID_IS_INPUT(pid)) {
@@ -111,9 +110,9 @@ static GF_FilterPacket *gf_filter_pck_new_alloc_internal(GF_FilterPid *pid, u32

 	count = gf_fq_count(pid->filter->pcks_alloc_reservoir);
 	if (count) {
+		GF_PckQueueEnum pck_enum_state;
+		memset(&pck_enum_state, 0, sizeof(GF_PckQueueEnum));
 		pck_enum_state.data_size = data_size;
-		pck_enum_state.closest = NULL;
-		pck_enum_state.pck = NULL;
 		gf_fq_enum(pid->filter->pcks_alloc_reservoir, pck_queue_enum, &pck_enum_state);
 		pck = pck_enum_state.pck;
 		closest = pck_enum_state.closest;

diff --git a/src/filter_core/filter_session.c b/src/filter_core/filter_session.c
index 7d4229f07..b6c57f5a5 100644
--- a/src/filter_core/filter_session.c
+++ b/src/filter_core/filter_session.c
@@ -729,7 +729,7 @@ void gf_fs_post_task_ex(GF_FilterSession *fsess, gf_fs_task_callback task_fun, G

 	//only flatten calls if in main thread (we still have some broken filters using threading
 	//that could trigger tasks
-	if ((force_direct_call || fsess->direct_mode) && fsess->tasks_in_process && gf_th_id()==fsess->main_th.th_id) {
+	if ((force_direct_call || fsess->direct_mode) && !filter->in_process && fsess->tasks_in_process && (gf_th_id()==fsess->main_th.th_id)) {
 		GF_FSTask atask;
 		u64 task_time = gf_sys_clock_high_res();
 		memset(&atask, 0, sizeof(GF_FSTask));
